    ofl_rmManual: ['This removes OrivenAI’s record only. The ad on {platform} isn’t changed.', 'Dit verwijdert alleen de registratie in OrivenAI. De advertentie op {platform} verandert niet.', 'Dadurch wird nur der Eintrag in OrivenAI entfernt. Die Anzeige auf {platform} bleibt unverändert.', 'Cela supprime uniquement l’enregistrement dans OrivenAI. L’annonce sur {platform} n’est pas modifiée.', 'Esto solo elimina el registro de OrivenAI. El anuncio en {platform} no cambia.', 'Isto remove apenas o registo da OrivenAI. O anúncio no {platform} não é alterado.'],
    ofl_rmProvider: ['This removes the campaign from OrivenAI on every device. It stays on {platform} — pause or delete it there if you don’t want it to run.', 'Dit verwijdert de campagne op elk apparaat uit OrivenAI. Hij blijft staan in {platform} — pauzeer of verwijder hem daar als hij niet moet lopen.', 'Dadurch wird die Kampagne auf allen Geräten aus OrivenAI entfernt. Sie bleibt in {platform} — pausiere oder lösche sie dort, wenn sie nicht laufen soll.', 'Cela retire la campagne d’OrivenAI sur tous les appareils. Elle reste sur {platform} — mettez-la en pause ou supprimez-la là-bas si vous ne voulez pas qu’elle soit diffusée.', 'Esto quita la campaña de OrivenAI en todos los dispositivos. Sigue en {platform}: páusala o elimínala allí si no quieres que se publique.', 'Isto remove a campanha da OrivenAI em todos os dispositivos. Ela continua no {platform} — pause-a ou apague-a lá se não quiser que seja veiculada.'],
    ofl_rmProviderStatus: ['This removes the campaign from OrivenAI on every device. It stays on {platform} (currently {status}) — pause or delete it there if you don’t want it to run.', 'Dit verwijdert de campagne op elk apparaat uit OrivenAI. Hij blijft staan in {platform} (nu {status}) — pauzeer of verwijder hem daar als hij niet moet lopen.', 'Dadurch wird die Kampagne auf allen Geräten aus OrivenAI entfernt. Sie bleibt in {platform} (derzeit {status}) — pausiere oder lösche sie dort, wenn sie nicht laufen soll.', 'Cela retire la campagne d’OrivenAI sur tous les appareils. Elle reste sur {platform} (actuellement {status}) — mettez-la en pause ou supprimez-la là-bas si vous ne voulez pas qu’elle soit diffusée.', 'Esto quita la campaña de OrivenAI en todos los dispositivos. Sigue en {platform} (ahora {status}): páusala o elimínala allí si no quieres que se publique.', 'Isto remove a campanha da OrivenAI em todos os dispositivos. Ela continua no {platform} (atualmente {status}) — pause-a ou apague-a lá se não quiser que seja veiculada.'],
    ofl_rmDraft: ['This deletes the draft from OrivenAI on every device. Nothing was ever sent to {platform}.', 'Dit verwijdert het concept op elk apparaat uit OrivenAI. Er is nooit iets naar {platform} verstuurd.', 'Dadurch wird der Entwurf auf allen Geräten aus OrivenAI gelöscht. An {platform} wurde nie etwas gesendet.', 'Cela supprime le brouillon d’OrivenAI sur tous les appareils. Rien n’a jamais été envoyé à {platform}.', 'Esto elimina el borrador de OrivenAI en todos los dispositivos. Nunca se envió nada a {platform}.', 'Isto apaga o rascunho da OrivenAI em todos os dispositivos. Nada foi alguma vez enviado para o {platform}.'],
